			[2174,'Documento de identidad del titular','fotocopia certificada de dos primeras hojas y ultimo domicilio (autoridad certificante: Juzgados, Escribanos y en Capital Federal: Centros de Gestión y Participación) con la correspondiente legalización del Colegio de Escribanos cuando sea necesario (certificaciones en extraña jurisdicción)'],
			[2175,'Documento de identidad cónyuge','fotocopia certificada de dos primeras hojas y ultimo domicilio (autoridad certificante: Juzgados, Escribanos y en Capital Federal: Centros de Gestión y Participación) con la correspondiente legalización del Colegio de Escribanos cuando sea necesario (certificaciones en extraña jurisdicción)'],
			[2177,'Formulario ANSES P.S. 2.14','Con firma certificada por autoridad policial (con rango de oficial o superior), judicial, escribano o funcionario del Centro de Gestión y Participación (este último solo para Capital Federal). Firmar en presencia del certificante donde se indica con X.'],
			[2541,'Form.Certificación Negativa IPS','Con firma certificada por autoridad policial (con rango de subteniente o superior), judicial, escribano o funcionario del Centro de Gestión y Participación (este último solo para Capital Federal). Firmar en presencia del certificante donde se indica con X.'],
			[2825,'DOCENTES: CEC 15 (Privados. Pcia. Bs. As.)','Para escuelas enseñanza privada en Pcia. de Buenso Aires; lo extiende el colegio y se certifica en DIPREGEP, calle 12 y 51, Torre 1, piso 10, La Plata'],
			[2826,'DOCENTES: Form. P.S. 6.268 (Cap. Fed. Privados)','Lo extiende el colegio, se certifica en Direccion General de Eduación de Gestión Privada, Santa Fé 4358, piso 1°, Capital Federal.  Autorizados a certificar: Areas, María Liliana o Boratto, Mercedes (Según Circular GP 61-05 ANSES)'],
			[2827,'DOCENTES:Form P.S. 6.268 (Cap. Fed. Ens. Pública)','Lo extiende el colegio, se certifica en Direccion Administrativa Docente, Avda. Paseo Colón 255, Capital Federal.  Autorizados a certificar: Medela Isabel o Ramírez Marcos (Según Circular GP 61-05 ANSES)  En caso de revistar en varios establecimientos, se solicita en el que tiene mayor carga horaria.'],
			[2828,'DOCENTES: Renuncia Condicionada dec. 8820','SOLO DOCENTES ENSEÑANZA PUBLICA  Se solicita en el establecimiento en que revista actualmente, juntamente con la certificacion de servicios y remuneraciones.'],
			[2829,'DOCENTES: P.S. 6.268 (Publicos- serv. anteriores a','Extiende el establecimiento, y se certifica en el Mrio. de Educación, Ciencia y Tecnología, Avda. Santa Fé 1548, piso 3 contrafrente, Capital Federal.'],
			[2830,'DOCENTES: Ens. Pública en la Pcia. de Buenos Aires','Reconocimiento de Servicios ante IPS, previa gestion del Codigo Jubilatorio en Direccion General de escuelas, direccion de jubilñaciones, calle 3 número 840, La Plata'],
			[2831,'DOCENTES: P.S. 6.268. (Pcia. Bs. As. Ens. Privada)','Lo extiende el colegio, se certifica en DIPREGEP, Calle 12 y 51, Torre 1, piso 10ireccion General de Eduación de Gestión Privada, Santa Fé 4358, piso 10 La Plata.  Autorizados a certificar: Mendy, Ramon Jorge (Según Circular GP 78-05 ANSES)'],
			[3799,'Form.ANSES - Pensión graciable','Con firma certificada por autoridad policial (con rango de subteniente o superior), judicial, escribano o funcionario del Centro de Gestión y Participación (este último solo para Capital Federal). Firmar en presencia del certificante donde se indica con X.'],
